// Single use: only an unused, unexpired code returns its workspace.
func (q *Queries) RedeemWorkerEnrollCode(ctx context.Context, codeHash []byte) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, redeemWorkerEnrollCode, codeHash)
	var workspace_id pgtype.UUID
	err := row.Scan(&workspace_id)
	return workspace_id, err
}

const refreshWorkerDeviceState = `-- name: RefreshWorkerDeviceState :exec
UPDATE public.worker_devices d
SET state = CASE
        WHEN EXISTS (
            SELECT 1 FROM public.worker_jobs j
            WHERE j.device_id = d.id AND j.state IN ('LEASED', 'RUNNING', 'CANCELLING')
        ) THEN 'busy'
        WHEN d.last_seen_at IS NOT NULL AND d.last_seen_at >= $1::timestamptz THEN 'online'
        ELSE 'offline' END
WHERE d.id = $2 AND d.revoked_at IS NULL
`

type RefreshWorkerDeviceStateParams struct {
	OnlineAfter pgtype.Timestamptz
	DeviceID    pgtype.UUID
}

func (q *Queries) RefreshWorkerDeviceState(ctx context.Context, arg RefreshWorkerDeviceStateParams) error {
	_, err := q.db.Exec(ctx, refreshWorkerDeviceState, arg.OnlineAfter, arg.DeviceID)
	return err
}

const reissueWorkerLease = `-- name: ReissueWorkerLease :one
UPDATE public.worker_jobs
SET lease_token_hash = $1, lease_expires_at = $2,
    leased_at = $3, updated_at = $3
WHERE workspace_id = $4 AND device_id = $5 AND state = 'LEASED'
  AND leased_at < $6
RETURNING id, workspace_id, execution_id, step_id, required_capabilities, state, device_id, lease_token_hash, lease_expires_at, attempt, result, idempotency_key, payload, progress, progress_seq, leased_at, interrupted_at, created_at, updated_at, finished_at
`

type ReissueWorkerLeaseParams struct {
	LeaseTokenHash []byte
	LeaseExpiresAt pgtype.Timestamptz
	Now            pgtype.Timestamptz
	WorkspaceID    pgtype.UUID
	DeviceID       pgtype.UUID
	PollStartedAt  pgtype.Timestamptz
}

// Rotates the lease token of the job the device holds in LEASED state, i.e.
// leased but never heartbeated nor reported: the poll response that carried
// the first token was lost. Same attempt; RUNNING or CANCELLING jobs are not
// touched. Only a poll that started after the lease was issued may rotate
// it (leased_at < poll_started_at), so a stale poll still open on a dead
// connection never replaces a token already delivered. leased_at moves to
// now: a reissue is a new issuance. The unique index
// worker_jobs_one_active_per_device keeps it to one row.
func (q *Queries) ReissueWorkerLease(ctx context.Context, arg ReissueWorkerLeaseParams) (WorkerJob, error) {
	row := q.db.QueryRow(ctx, reissueWorkerLease,
		arg.LeaseTokenHash,
		arg.LeaseExpiresAt,
		arg.Now,
		arg.WorkspaceID,
		arg.DeviceID,
		arg.PollStartedAt,
	)
	var i WorkerJob
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.ExecutionID,
		&i.StepID,
		&i.RequiredCapabilities,
		&i.State,
		&i.DeviceID,
		&i.LeaseTokenHash,
		&i.LeaseExpiresAt,
		&i.Attempt,
		&i.Result,
		&i.IdempotencyKey,
		&i.Payload,
		&i.Progress,
		&i.ProgressSeq,
		&i.LeasedAt,
		&i.InterruptedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.FinishedAt,
	)
	return i, err
}

